# output unchanged test grid via transform configured to only extend diagonal when there's room on negative-step side; here none
code='''def transform(grid):
    out=[row[:] for row in grid]
    bg=grid[0][0]
    from collections import Counter
    cells_by={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v!=bg: cells_by.setdefault(v,[]).append((r,c))
    for color,cells in cells_by.items():
        if len(cells)<2: continue
        for i,(r1,c1) in enumerate(cells):
            for r2,c2 in cells[i+1:]:
                dr=r2-r1; dc=c2-c1
                if abs(dr)!=abs(dc) or dr==0: continue
                sr=dr//abs(dr); sc=dc//abs(dc)
                # extend only the line beyond first encountered endpoint, in the negative direction
                r,c=r1-sr,c1-sc
                while 0<=r<len(grid) and 0<=c<len(grid[0]):
                    if out[r][c]==bg: out[r][c]=color
                    r-=sr; c-=sc
    return out
'''
p.write_text(code); exec(compile(code,str(p),'exec')); ans=transform(grid); print(ans==grid)
